import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fig import strip,svg
from fig3 import *
PG.configure('/home-puja/',[('','A Simple Home Pūjā','Step by Step, and What Each Step Means')],'navy','Home Pūjā','Lord','Home Pūjā')
PG.CFG.update(backurl='/hymns/',backname='Hymns and Mantras')
PG.OUT='outp/home-puja/'
GA=lambda x,y,s=1: g(x,y,s,ganesha())
SH=lambda x=280,y=150,s=1: g(x,y,s,shrine())+g(x,y-6,s*.55,ganesha(seat=False))
i=0
pp=[foreword(i,['Pūjā is simply this: receiving God as an honoured guest in your home. You invite, offer a seat, water, fragrance, flowers, light and food, you circle and bow, and you take back what was offered as grace.','This article walks through a simple home pūjā step by step, and answers the questions people actually ask: <b>why do we do ārati? why tilaka? why ring a bell? what is prasāda?</b> It ends with a five-minute version for busy days.'],[('z','Do I need a priest or Sanskrit for this?'),('b','No. A clean place, a lamp, a flower and a sincere mind. The Gītā itself says a leaf or a little water offered with love is accepted.')]),
 glance([('What','Worship of God as an honoured guest'),('Short form','Five offerings (pañcopacāra): fragrance, flower, incense, lamp, food'),('Full form','Sixteen offerings (ṣoḍaśopacāra)'),('Begin with','Ācamana, saṅkalpa, Gaṇeśa'),('End with','Ārati, pradakṣiṇā, namaskāra, prasāda'),('Time','Five minutes to an hour'),('Needed','Sincerity; everything else is optional')],svg(560,150,'A home shrine with a lamp and flowers',SH(280,145,1.2)+g(140,140,1.4,lamp())+g(420,140,1,lotus()))),
 reading('what','WHAT IS PŪJĀ','God as the honoured guest',svg(560,150,'A host welcoming a guest with folded hands',g(200,140,1.2,namaste('#1d6fb8'))+SH(380,145,1)),['<b>The idea.</b> The steps of pūjā follow the way an honoured guest was received in an old Indian home: welcome, a seat, water for the feet and hands, a bath, fresh clothes, fragrance, flowers, light, a meal, betel, and a respectful farewell.','<b>The word.</b> Pūjā means worship or honouring; each act of service is an upacāra.','<b>How many.</b> There are short and long forms: five services (pañcopacāra), ten, sixteen (ṣoḍaśopacāra), and longer temple forms.','<b>Why a form at all.</b> The form gives the hands something to do while the heart attends. It is a discipline of attention.'],[('z','So I’m treating God like a guest?'),('b','Like the most welcome guest you could ever have. That’s the whole emotional key.')],'Receive God <b>as your guest</b>.'),
 cards('prepare','BEFORE YOU BEGIN','What you need',fig_row('Lamp, bell, kalaśa, flowers and incense',[(lamp(),1.3),(bell(),1.3),(kalasha(),1),(lotus(),1.2),(incense(),1.1)],['lamp','bell','water pot','flowers','incense'],gy=160),[('🛁','Yourself','A bath and clean clothes; a calm few minutes.'),('🧹','The place','A clean corner, shelf or room; many face east or north.'),('🖼️','The image','A picture, image (mūrti), śālagrāma, liṅga or simply a lamp.'),('🪔','The things','Lamp, water, a flower, incense, a little food. A bell and kuṅkuma if you have them.')],[('z','What if I don’t have all this?'),('b','Use what you have. A lamp and water are enough to begin; the rest grows with habit.')],'A clean place and <b>a quiet mind</b>.'),
 reading('acamana','STEP 1 · ĀCAMANA','Sipping water to begin',svg(560,150,'Water in a cupped palm',g(280,120,2,'<path d="M-30 0 q30 20 60 0 q-10 -14 -30 -14 q-20 0 -30 14z" fill="#c98a5a"/><ellipse cy="-4" rx="16" ry="5" fill="#8fb8de"/>')),['<b>What.</b> Three small sips of water from the right palm, each with a name of God (commonly Keśava, Nārāyaṇa, Mādhava in Vaiṣṇava homes).','<b>Why.</b> Inner purification: as a bath cleans the body, the sips are said to clean speech and mind before worship.','<b>Prāṇāyāma.</b> Many follow with a few slow breaths to settle the mind.','<b>Simple version.</b> Wash hands and feet, sip a little water, and take three calm breaths.'],None,'Clean inside <b>before you begin</b>.'),
 reading('sankalpa','STEP 2 · SAṄKALPA','Saying what you are doing',svg(560,150,'Water and rice held in the hand',g(280,120,2,'<path d="M-30 0 q30 20 60 0 q-10 -14 -30 -14 q-20 0 -30 14z" fill="#c98a5a"/>'+''.join(f'<circle cx="{x}" cy="-6" r="2" fill="#fff" stroke="none"/>' for x in (-8,-2,4,10)))),['<b>What.</b> A short statement of intention: who is worshipping, where, when, which deity, and why. Formal saṅkalpas name the place and time in traditional reckoning.','<b>How.</b> Hold a little water, rice or a flower in the right hand, state the intention, and release it.','<b>Why.</b> It turns a routine into a deliberate act; you know what you are doing and for whom.','<b>Simple version.</b> In your own language: “Today I worship the Lord, for the good of my family and all beings.”'],[('z','Can I say it in Kannada or English?'),('b','Of course. God understands every language. Sanskrit is lovely, not compulsory.')],'Know <b>what you are doing</b>.'),
 verse('ganesha','Gaṇeśa first','Why every pūjā begins with Gaṇeśa',['śuklāmbaradharaṃ viṣṇuṃ śaśivarṇaṃ caturbhujam','prasannavadanaṃ dhyāyet sarvavighnopaśāntaye'],svg(200,140,'Gaṇeśa',GA(100,135,1.2)),'One should meditate on the one clad in white, all-pervading, moon-coloured, four-armed, with a gracious face, for the calming of all obstacles.',[('śukla-ambara-dharam','wearing white'),('viṣṇum','the all-pervading'),('śaśi-varṇam','moon-coloured'),('catur-bhujam','four-armed'),('prasanna-vadanam','with a gracious face'),('sarva-vighna-upaśāntaye','for the calming of all obstacles')],'Gaṇeśa is remembered first so that the rest of the worship goes without hindrance. This verse is recited in many homes as the very first line of any pūjā.',k='<b>Obstacles calmed</b>, then begin.',note='Text as on our <a href="/ganesha/hymns/daily-slokas/">Gaṇeśa daily ślokas</a> page.'),
 reading('dhyana','STEP 3 · DHYĀNA AND ĀVĀHANA','Remembering and inviting',svg(560,150,'A person with closed eyes before the shrine',g(180,140,1.2,namaste('#7a3fa0'))+SH(380,145,1)),['<b>Dhyāna.</b> Close your eyes and picture the deity’s form, as described in a meditation verse or as you know it.','<b>Āvāhana.</b> Invite God to be present in the image or lamp before you. Many show an inviting gesture with joined palms.','<b>Why.</b> The image is not worshipped as stone or metal; it is a place where you ask the Lord to receive your service.','<b>Āsana.</b> Then offer a seat: a flower or a few grains of rice placed at the base.'],[('z','So the idol isn’t God?'),('b','The tradition says God is everywhere and chooses to receive worship there. The image is the meeting point.')],'Picture, invite, <b>offer a seat</b>.'),
 cards('sixteen','THE SIXTEEN SERVICES','Ṣoḍaśopacāra at a glance',svg(560,60,'Sixteen small dots',''.join(f'<circle cx="{30+j*33}" cy="30" r="9" fill="{"#e0a800" if j%2 else "#c0392b"}"/>' for j in range(16))),[('1–3','Dhyāna, āvāhana, āsana','Remember, invite, offer a seat.'),('4–6','Pādya, arghya, ācamanīya','Water for the feet, the hands and to sip.'),('7–9','Snāna, vastra, yajñopavīta','A bath, clothing, the sacred thread or ornaments.'),('10–12','Gandha, puṣpa, dhūpa','Sandal paste, flowers, incense.'),('13–14','Dīpa, naivedya','A lamp and food.'),('15–16','Tāmbūla/nīrājana, namaskāra','Betel or ārati, then pradakṣiṇā and bowing.')],None,'<b>Sixteen</b> ways to serve a guest.',intro='Lists differ by tradition: some count dhyāna separately, some end with mantrapuṣpa or a prayer for pardon. This is a common arrangement.'),
 reading('water','WATER OFFERINGS','Pādya, arghya, ācamanīya, snāna',svg(560,150,'A small vessel pouring water',g(220,130,1.5,kalasha())+'<path d="M250 90 q40 10 50 40" fill="none" stroke="#8fb8de" stroke-width="4"/>'+g(340,140,1,lotus())),['<b>Pādya.</b> A little water at the feet, as a tired traveller’s feet are washed.','<b>Arghya.</b> Water for the hands, often with flowers and rice: the mark of respect to a guest.','<b>Ācamanīya.</b> Water to sip.','<b>Snāna.</b> A bath: plain water, or pañcāmṛta (milk, curd, ghee, honey, sugar) on special days. At home a few drops sprinkled on the image, or on a flower, is enough.'],None,'Water first, <b>as for any guest</b>.'),
 reading('tilaka','WHY TILAKA?','Gandha, kuṅkuma and the mark on the forehead',fig_row('Four kinds of forehead marks',[(face('vaishnava'),1),(face('shaiva'),1),(face('kumkum'),1),(face('bindi'),1)],['ūrdhva-puṇḍra','tripuṇḍra','kuṅkuma','bindu'],gy=160),['<b>To God.</b> Sandal paste (gandha) and kuṅkuma are offered to the deity as fragrance and adornment.','<b>To ourselves.</b> After worship we wear it as prasāda on the forehead, between the brows, where many teachers place the seat of attention. (Interpretation.)','<b>Different marks.</b> Vaiṣṇavas wear the upright ūrdhva-puṇḍra, Śaivas the three horizontal lines of ash (tripuṇḍra), many wear a dot of kuṅkuma; each marks a tradition.','<b>Why wear it.</b> It says “I have worshipped today”; a reminder through the day, and a sign of belonging.'],[('z','Is the tilaka the same for everyone?'),('b','No: it tells you the tradition. Upright for Viṣṇu, lines of ash for Śiva, red for Devī. All say: God first.')],'A mark that <b>remembers worship</b>.'),
 reading('flowers','WHY FLOWERS?','Puṣpa, akṣata and sacred leaves',fig_row('Flowers, tulasī, bilva and dūrvā',[(lotus(),1.3),(tulasi(),1),(leaf(),1.3),(durva(),1.4)],['flower','tulasī','bilva','dūrvā'],gy=160),['<b>Flowers.</b> The most beautiful thing in nature, offered back to its source; fresh, unsmelled, and whole.','<b>By deity.</b> Tulasī for Viṣṇu and Kṛṣṇa, bilva for Śiva, dūrvā and red flowers for Gaṇeśa, red flowers for Devī. Each pairing has its stories.','<b>Akṣata.</b> Unbroken rice, often with turmeric or kuṅkuma: “unbroken”, standing for wholeness; used when an item is not at hand.','<b>Puṣpāñjali.</b> At the end, flowers offered with both hands together.'],None,'The best of nature, <b>given back</b>.'),
 reading('incense','WHY INCENSE?','Dhūpa',svg(560,150,'Incense smoke rising',g(240,140,1.8,incense())+g(340,140,1.8,incense())),['<b>Fragrance.</b> Incense honours the guest with the sense of smell, as sandal paste does with touch.','<b>Rising smoke.</b> It rises and spreads; many see it as prayer going upward. (Interpretation.)','<b>Cleansing.</b> Traditionally incense and resin also cleared the air of insects and odours.','<b>Care.</b> One stick is enough; keep a window open and the ash contained.'],None,'Fragrance <b>for the guest</b>.'),
 reading('lamp','WHY LIGHT A LAMP?','Dīpa',svg(560,150,'A row of oil lamps',''.join(g(140+j*70,130,1.5,lamp()) for j in range(5))),['<b>Light.</b> The lamp honours God with sight, and is itself an image of knowledge driving out ignorance.','<b>Ghee or oil.</b> A ghee lamp is traditional; sesame oil is common. The wick is lit facing east or north in many homes.','<b>Morning and evening.</b> Many homes light the lamp at dawn and at dusk even when there is no full pūjā.','<b>The lamp as deity.</b> In many homes the lamp itself is worshipped as a form of Devī or of light.'],[('z','Why does every pūjā have a lamp?'),('b','Because nothing is seen without light, including God. Lighting a lamp is the shortest pūjā there is.')],'Light <b>drives out darkness</b>.'),
 reading('bell','WHY RING A BELL?','Ghaṇṭā and śaṅkha',fig_row('A bell and a conch',[(bell(),2),(conch(),2)],['bell','conch'],gy=160),['<b>Announcing.</b> The bell is rung at the start of worship, at the bath, while offering incense, lamp and food, and through ārati: an announcement that worship is under way.','<b>Gathering the mind.</b> Its clear sound draws scattered attention to the present. (Interpretation.)','<b>Driving away the unwelcome.</b> Traditional texts say the sound welcomes the divine and drives out the undivine.','<b>The conch.</b> Blown at the start or end in many homes and temples; Viṣṇu holds it as Pāñcajanya.'],None,'A sound that <b>gathers the mind</b>.'),
 verse('naivedya','What is naivedya?','Food offered first to God',['patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati','tadahaṃ bhaktyupahṛtamaśnāmi prayatātmanaḥ'],svg(200,140,'A plate with fruit, flowers and water',g(100,110,2,plate())+g(80,104,1,banana())+g(120,104,1,lotus())),'Whoever offers me with devotion a leaf, a flower, a fruit, or water, that devotion-offering of the pure-hearted I accept. (Bhagavad Gītā 9.26)',[('patram','a leaf'),('puṣpam','a flower'),('phalam','a fruit'),('toyam','water'),('bhaktyā','with devotion'),('aśnāmi','I accept, I partake')],'<b>Naivedya</b> is the food offered to God before anyone eats: cooked rice, fruit, milk, sweets, whatever the house eats. Water is sprinkled around it, it is offered with a prayer, and after a pause it becomes prasāda. Kṛṣṇa’s verse sets the standard: not the cost, but the devotion.',k='A leaf <b>given with love</b> is enough.',note='Text as on our <a href="/vishnu/bhagavad-gita/chapter-9/">Gītā, chapter 9</a> page.'),
 reading('arati','WHY DO WE DO ĀRATI?','Nīrājana, the waving of lights',svg(560,160,'An ārati plate with a camphor flame waved before Gaṇeśa',SH(380,150,1.1)+g(200,110,1.6,arati())+'<path d="M160 70 q40 -40 80 0 q-40 40 -80 0" fill="none" stroke="#e0a800" stroke-width="2" stroke-dasharray="4 4"/>'),['<b>What.</b> A lamp or camphor flame on a plate is waved in circles before the deity, usually with a bell and a song or verse.','<b>Why.</b> It shows every part of the form in light, as one would look lovingly at a beloved guest; it also marks the climax of the pūjā.','<b>Why camphor.</b> Camphor burns away completely, leaving no ash: an image of the ego burning away in God. (A common interpretation.)','<b>Taking ārati.</b> Afterwards everyone passes their palms over the flame and touches their eyes: receiving the light as grace.'],[('z','Why do we put our hands over the flame and then on our eyes?'),('b','To take the blessing of the light into ourselves. Grace given, grace received.')],'Light shown, <b>light received</b>.'),
 reading('pradakshina','WHY PRADAKṢIṆĀ AND NAMASKĀRA?','Circling and bowing',svg(560,160,'A person circling the shrine clockwise',SH(280,150,1)+'<ellipse cx="280" cy="110" rx="140" ry="40" fill="none" stroke="#1d6fb8" stroke-width="2" stroke-dasharray="6 5"/>'+g(150,140,1,namaste('#c0392b'))),['<b>Pradakṣiṇā.</b> Walking clockwise around the deity, keeping God on your right, the side of honour. At home, turning around in place is the accepted substitute.','<b>Why clockwise.</b> As the planets circle the sun, the devotee’s life circles God as its centre. (Interpretation.)','<b>Namaskāra.</b> Bowing with joined palms; the full prostration (sāṣṭāṅga, “with eight limbs”) touches forehead, chest, hands, knees and feet to the ground.','<b>Meaning.</b> “Not I, but you”: the ego bows.'],None,'God at the centre, <b>the ego bowed</b>.'),
 verse('samarpana','The closing offering','Giving it all back',['kāyena vācā manasendriyair vā','buddhyātmanā vā prakṛteḥ svabhāvāt','karomi yad yat sakalaṃ parasmai','nārāyaṇāyeti samarpayāmi'],svg(200,140,'Folded hands before a lamp',g(80,130,1.3,namaste('#1d6fb8'))+g(150,130,1.5,lamp())),'Whatever I do, by body, speech, mind or senses, by intellect or self, or by the natural bent of my nature, all of it I offer to the Supreme, to Nārāyaṇa.',[('kāyena','by the body'),('vācā','by speech'),('manasā','by the mind'),('indriyaiḥ','by the senses'),('prakṛteḥ svabhāvāt','from my natural bent'),('samarpayāmi','I offer')],'Many close every pūjā with this verse (from the Bhāgavata, 11.2.36), offering not just the pūjā but the whole day. Śaivas and Śāktas say the same with the name of their deity. Then many ask pardon for any mistakes in the worship.',k='Offer <b>the whole day</b>, not just the pūjā.',note='Text as on our <a href="/vishnu/vishnu-sahasranama/part-10/">Viṣṇu Sahasranāma, part 10</a> page.'),
 verse('prasada','What is prasāda?','Grace you can eat',['brahmārpaṇaṃ brahmahavirbrahmāgnau brahmaṇā hutam','brahmaiva tena gantavyaṃ brahmakarmasamādhinā'],svg(200,140,'Hands receiving prasāda',g(100,110,2,plate())+g(90,104,1,modaka())+g(112,104,1,laddu())),'The offering is Brahman, the oblation is Brahman, poured by Brahman into the fire that is Brahman; Brahman is reached by the one absorbed in action as Brahman. (Bhagavad Gītā 4.24)',[('arpaṇam','the act of offering'),('haviḥ','the oblation'),('agnau','in the fire'),('hutam','offered'),('gantavyam','to be reached'),('samādhinā','by absorption')],'<b>Prasāda</b> means grace, clarity, favour. Food offered to God and returned is no longer just food: it is received with the right hand, never wasted or refused, shared with others. Many recite this Gītā verse before every meal, so that eating itself becomes an offering.',k='Food offered becomes <b>grace returned</b>.',note='Text as on our <a href="/vishnu/bhagavad-gita/chapter-4/">Gītā, chapter 4</a> page.'),
 reading('five','A FIVE-MINUTE PŪJĀ','Pañcopacāra for busy days',fig_row('Five offerings: sandal, flower, incense, lamp, food',[(face('kumkum'),.6),(lotus(),1.2),(incense(),1),(lamp(),1.3),(laddu(),1.4)],['gandha','puṣpa','dhūpa','dīpa','naivedya'],gy=160),['<b>1. Begin.</b> Wash, sip water, a breath; remember Gaṇeśa.','<b>2. Five offerings.</b> Gandha (a dot of sandal or kuṅkuma), puṣpa (a flower), dhūpa (incense), dīpa (the lamp), naivedya (a fruit, milk or a sweet).','<b>3. Ārati.</b> Wave the lamp or camphor three times, with a bell if you have one.','<b>4. Bow and take prasāda.</b> A namaskāra, a word of thanks, and share the offered food.'],[('z','Five minutes counts?'),('b','Every day for five minutes beats an hour once a month. The habit is the pūjā.')],'Five offerings, <b>five minutes</b>.'),
 cards('faq','COMMON QUESTIONS','Short, honest answers',svg(560,80,'Question marks',''.join(lab(60+j*110,50,'?',36) for j in range(5))),[('🖼️','No image?','A lamp, a picture or even the sun will do; many traditions worship the formless through a flame.'),('🗓️','Missed a day?','Resume the next day. Regularity matters more than perfection.'),('📿','No mantras?','The deity’s name, said with attention, is enough. Learn a few verses over time.'),('🍽️','What to offer?','What your home eats that day, made with care. Many avoid onion and garlic in offered food.')],None,'Sincerity <b>over perfection</b>.'),
 reading('children','PŪJĀ WITH CHILDREN','Bringing them in',svg(560,150,'Children ringing a bell and holding a flower before the shrine',SH(380,145,1)+g(180,140,1,child())+g(240,140,1,child())+g(210,80,1,bell())),['<b>Give them a job.</b> Ring the bell, pick the flower, carry the water, hold the plate at ārati.','<b>One verse.</b> Teach one short verse, say the Gaṇeśa verse, and let them lead it.','<b>Explain one step.</b> One “why” a week: why the lamp, why the bell, why prasāda.','<b>Make it theirs.</b> Let them place their own offering. Children who belong to the pūjā keep it as adults.'],None,'Give every child <b>a job</b>.'),
 end(i,['<b>Pūjā.</b> Receiving God as an honoured guest.','<b>Begin.</b> Ācamana, saṅkalpa, Gaṇeśa, dhyāna and invitation.','<b>Serve.</b> Water, tilaka, flowers, incense, lamp, food.','<b>Close.</b> Ārati, pradakṣiṇā, namaskāra, the closing offering.','<b>Receive.</b> Prasāda: grace returned.'],'Read next: our <a href="/sixteen-samskaras/">sixteen saṃskāras</a>, the rites that mark a life.','A simple home pūjā'),
 sources([('Practice:','Common household practice; Wikipedia, “Upachara” (lists of five and sixteen services).'),('Verses:','Gaṇeśa dhyāna verse (our daily ślokas page); Bhagavad Gītā 9.26 and 4.24; Bhāgavata 11.2.36 (as on our Sahasranāma page).')],'lists of the sixteen services differ by tradition; interpretations of the lamp, bell, camphor and pradakṣiṇā are marked as such.','Meanings in our own words.')]
build(i,'HOW-TO · STEP BY STEP · WHY WE DO IT',covart('A home shrine with Gaṇeśa, a lamp, a bell and flowers',g(220,196,1.6,shrine())+g(220,190,.9,ganesha(seat=False))+g(90,196,1.6,lamp())+g(350,196,1.6,arati())+g(380,90,1.5,bell())+g(70,100,1.2,lotus())),'Step by step, and what each step means','The <b>steps</b> of a home pūjā in order, and <b>why</b>: the tilaka, flowers, lamp, bell, naivedya, <b>ārati</b>, pradakṣiṇā and <b>prasāda</b>, with a five-minute version.','How to do a simple home pūjā step by step, and what each step means: why we light a lamp, why tilaka, why ring a bell, why we do ārati, what naivedya and prasāda are, pradakṣiṇā and namaskāra, with a five-minute pūjā for busy days.',pp)
print('puja ok')
